"use client";

/**
 * Demo mode: the read-only build that runs without the Python backend.
 *
 * `NEXT_PUBLIC_DEMO_MODE=1` swaps every API call for the pre-rendered sample
 * projects in `public/demo/demo-data.json` (generated by
 * `scripts/make-demo-assets.py`). Editing still works: settings changes are kept
 * in localStorage so the studio feels alive, but anything that needs FFmpeg,
 * Whisper or a filesystem is refused with an explanation.
 */

import { DEMO_APP_NOTE, DEMO_MODE, demoBundle } from "@/lib/demo-config";
import type { Project, RenderSettings } from "@/lib/types";

export { DEMO_APP_NOTE, DEMO_MODE };

const SETTINGS_KEY = "cliptok-demo-settings";

/** Demo mode has no server, so "unsupported" is a normal answer, not an error. */
export class DemoRestriction extends Error {
  constructor() {
    super(DEMO_APP_NOTE);
    this.name = "DemoRestriction";
  }
}

function readOverrides(): Record<string, RenderSettings> {
  if (typeof window === "undefined") return {};
  try {
    const raw = window.localStorage.getItem(SETTINGS_KEY);
    return raw ? (JSON.parse(raw) as Record<string, RenderSettings>) : {};
  } catch {
    return {};
  }
}

function writeOverride(projectId: string, settings: RenderSettings): void {
  if (typeof window === "undefined") return;
  try {
    const overrides = readOverrides();
    overrides[projectId] = settings;
    window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(overrides));
  } catch {
    /* private browsing: keep the in-memory state only */
  }
}

function withLocalSettings(project: Project): Project {
  const override = readOverrides()[project.id];
  if (!override) return project;
  return { ...project, settings: { ...project.settings, ...override } };
}

export const demoApi = {
  health: async () => demoBundle.health,

  listProjects: async (): Promise<Project[]> => demoBundle.projects.map(withLocalSettings),

  getProject: async (id: string): Promise<Project> => {
    const project = demoBundle.projects.find((item) => item.id === id);
    if (!project) throw new Error("This sample project is not part of the demo.");
    return withLocalSettings(project);
  },

  updateProject: async (
    id: string,
    payload: { name?: string; settings?: RenderSettings },
  ): Promise<Project> => {
    const project = await demoApi.getProject(id);
    if (payload.settings) writeOverride(id, payload.settings);
    return {
      ...project,
      name: payload.name ?? project.name,
      settings: payload.settings ?? project.settings,
    };
  },

  stickers: async () => ({ stickers: demoBundle.stickers }),

  share: async () => ({
    share: {
      slug: demoBundle.share.slug,
      quality: demoBundle.share.quality,
      path: `/s/${demoBundle.share.slug}/`,
      created_at: demoBundle.generated_at,
    },
  }),

  unshare: async (): Promise<void> => undefined,
};
